//! Shared marker vectors, independently generated by tools/private-repos-vectors/seal_off_marker.py.
use super::convert::{
    self, ActiveSealOff, SealOffConfig, SealOffMarker, SealOffMode, SealOffOpening,
};
use super::doc::{self, DocHeader, Opened};
use super::keys::{EpochKey, EpochKeys};
use super::tlv::{self, Fields};
use super::DocKind;
use serde_json::{json, Value};

fn number(v: &Value, key: &str) -> Option<u32> {
    v[key].as_u64().map(|n| u32::try_from(n).unwrap())
}
fn bytes(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}
fn id(v: &Value) -> [u8; 32] {
    bytes(v).try_into().unwrap()
}
fn marker(v: &Value) -> SealOffMarker {
    SealOffMarker {
        mode: if v["mode"] == "codeOnly" {
            SealOffMode::CodeOnly
        } else {
            SealOffMode::Everything
        },
        conversion_id: bytes(&v["conversionId"]).try_into().unwrap(),
        boundary_epoch: number(v, "boundaryEpoch").unwrap(),
        started_at_ms: v["startedAtMs"].as_str().unwrap().parse().unwrap(),
        replaces_epoch: number(v, "replacesEpoch"),
    }
}
fn marker_json(m: &SealOffMarker) -> Value {
    let mut v = json!({"mode": if m.mode == SealOffMode::CodeOnly { "codeOnly" } else { "everything" }, "conversionId": hex::encode(m.conversion_id), "boundaryEpoch": m.boundary_epoch, "startedAtMs": m.started_at_ms.to_string()});
    if let Some(e) = m.replaces_epoch {
        v["replacesEpoch"] = json!(e);
    }
    v
}
fn active_json(a: &ActiveSealOff) -> Value {
    match a {
        ActiveSealOff::None => json!({"kind":"none"}),
        ActiveSealOff::Unknown => json!({"kind":"unknown"}),
        ActiveSealOff::Active {
            epoch,
            height,
            marker,
            highest_epoch,
            replaces_through,
        } => {
            json!({"kind":"active", "epoch": epoch, "height": height, "marker": marker.as_ref().map(marker_json), "highestEpoch": highest_epoch, "replacesThrough": replaces_through})
        }
    }
}
fn active(v: &Value) -> ActiveSealOff {
    match v["kind"].as_str().unwrap() {
        "none" => ActiveSealOff::None,
        "unknown" => ActiveSealOff::Unknown,
        "active" => ActiveSealOff::Active {
            epoch: number(v, "epoch").unwrap(),
            height: v["height"].as_u64().unwrap(),
            highest_epoch: number(v, "highestEpoch").unwrap(),
            replaces_through: number(v, "replacesThrough"),
            marker: if v["marker"].is_null() {
                None
            } else {
                Some(marker(&v["marker"]))
            },
        },
        _ => panic!("unknown active result"),
    }
}

#[test]
#[allow(clippy::too_many_lines)] // shared vector operations are dispatched together, like the existing suites
fn seal_off_marker_shared_vectors() {
    let dir =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../forge-contracts/vectors");
    let mut count = 0;
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if !path
            .file_name()
            .unwrap()
            .to_str()
            .unwrap()
            .starts_with("seal_off_marker__")
        {
            continue;
        }
        let v: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        let inp = &v["input"];
        let expected = &v["expected"];
        let name = v["name"].as_str().unwrap();
        match inp["op"].as_str().unwrap() {
            "encoding" => {
                let m = marker(&inp["marker"]);
                assert!(m.encode() == bytes(&expected["value"]), "{name}: value");
                assert_eq!(
                    SealOffMarker::parse(&m.encode(), m.boundary_epoch),
                    Some(m.clone()),
                    "{name}"
                );
                let fields = Fields {
                    default_branch: Some("main".into()),
                    prev_epoch: Some(m.boundary_epoch - 1),
                    prev_epoch_key: Some(EpochKey::from_bytes(std::array::from_fn(|i| {
                        u8::try_from(i).unwrap()
                    }))),
                    seal_off: Some(m.encode()),
                    ..Fields::default()
                };
                assert!(
                    tlv::encode(&fields).as_slice() == bytes(&expected["tlv"]),
                    "{name}: TLV"
                );
                let keys = EpochKeys::derive(
                    &[0x11; 32],
                    m.boundary_epoch,
                    &EpochKey::from_bytes(std::array::from_fn(|i| u8::try_from(i + 32).unwrap())),
                );
                let header = DocHeader::new(DocKind::Config, [0x22; 32], m.boundary_epoch);
                let enc = doc::seal_with_nonce(
                    &keys,
                    &header,
                    &fields,
                    true,
                    std::array::from_fn(|i| u8::try_from(i).unwrap()),
                )
                .unwrap();
                assert!(enc == bytes(&expected["enc"]), "{name}: enc");
                let Opened::Readable(opened) = doc::open_with(&keys, &header, &enc, true) else {
                    panic!("{name}: open");
                };
                assert!(opened.seal_off == fields.seal_off, "{name}: retained");
            }
            "issue" => {
                let fields = tlv::parse(
                    &[1, 0, 5, b'T', b'i', b't', b'l', b'e', 65, 0, 2, 1, 2],
                    DocKind::Issue,
                    false,
                )
                .unwrap();
                assert_eq!(serde_json::to_value(fields).unwrap(), *expected);
            }
            "rule" => {
                let configs = inp["configs"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|c| SealOffConfig {
                        id: id(&c["id"]),
                        owner: id(&c["owner"]),
                        epoch: number(c, "epoch"),
                        private: c["private"].as_bool().unwrap(),
                        height: c["height"].as_u64().unwrap(),
                        opening: match c["opening"].as_str().unwrap() {
                            "opened" => SealOffOpening::Opened(c.get("sealOff").map(bytes)),
                            "otherKey" => SealOffOpening::OtherKey,
                            "unreadable" => SealOffOpening::Unreadable,
                            _ => panic!("opening"),
                        },
                    })
                    .collect::<Vec<_>>();
                assert_eq!(
                    active_json(&convert::active_seal_off(&configs, &id(&inp["owner"]))),
                    *expected,
                    "{name}"
                );
            }
            "decision" => {
                use convert::SealOffDecision as D;
                let result = match convert::seal_off_decision(
                    number(inp, "recorded"),
                    &active(&inp["active"]),
                    number(inp, "current"),
                    inp["flipped"].as_bool().unwrap(),
                    number(inp, "stated"),
                ) {
                    D::New => json!({"kind":"new"}),
                    D::Unknown => json!({"kind":"unknown"}),
                    D::Adopt(epoch) => json!({"kind":"adopt","epoch":epoch}),
                    D::Passed(epoch) => json!({"kind":"passed","epoch":epoch}),
                    D::Lagging(epoch) => json!({"kind":"lagging","epoch":epoch}),
                    D::Public(cutoff) => json!({"kind":"public","cutoff":cutoff}),
                };
                assert_eq!(result, *expected, "{name}");
            }
            "size" => {
                let m = marker(&inp["marker"]);
                let settings = crate::keyring::AnchorSettings {
                    default_branch: inp["settings"]["defaultBranch"].as_str().unwrap().into(),
                    protected_patterns: serde_json::from_value(
                        inp["settings"]["protectedPatterns"].clone(),
                    )
                    .unwrap(),
                    backend: crate::keyring::backend_object(0),
                    archived: false,
                };
                let fits =
                    crate::keyring::preflight_seal_off(&[0x11; 32], [0x22; 32], &settings, &m)
                        .is_ok();
                assert_eq!(fits, expected["fits"].as_bool().unwrap(), "{name}");
                let key = EpochKey::from_bytes([0; 32]);
                let content = crate::keyring::anchor_content(
                    crate::rules::v2::Visibility::Private,
                    &settings,
                    Some(crate::keyring::ChainLink {
                        prev: 2,
                        prev_key: Some(key.clone()),
                        skip_key: Some(key),
                        burned: false,
                    }),
                    Some(&m),
                );
                assert_eq!(
                    tlv::encode(&content.fields).len(),
                    usize::try_from(expected["tlvBytes"].as_u64().unwrap()).unwrap(),
                    "{name}"
                );
            }
            _ => panic!("unknown operation"),
        }
        count += 1;
    }
    assert_eq!(count, 49);
}
